    return cache.get_or_set(key, lambda: list(Post.objects.filter(tenant=tenant)), 60)

import time

def get_catalog(tenant):
    key = f"catalog:{tenant.pk}"
    data = cache.get(key)
    if data is not None:
        return data
    lock = f"{key}:lock"
    if cache.add(lock, "1", timeout=10):
        try:
            data = build_catalog(tenant)
            cache.set(key, data, 120)
        finally:
            cache.delete(lock)
        return data
    for _ in range(5):
        time.sleep(0.05)
        data = cache.get(key)
        if data is not None:
            return data
    return build_catalog(tenant)

