def validate_upload(uploaded):
    if uploaded.size > 10 * 1024 * 1024:
        raise ValidationError("Maximum size is 10 MB.")
    if uploaded.content_type not in {"image/png", "image/jpeg", "application/pdf"}:
        raise ValidationError("Unsupported type.")
    return uploaded

from django.http import FileResponse, Http404

def download(request, pk):
    report = get_object_or_404(Report, pk=pk, owner=request.user)
    try:
        handle = report.file.open("rb")
    except FileNotFoundError as exc:
        raise Http404("File missing") from exc
    return FileResponse(handle, as_attachment=True)

